
#[derive(Clone,PartialEq,Eq,PartialOrd,Ord,Hash)]struct GlobalPoly(Vec<(Vec<u32>,u32)>);
#[derive(Clone,PartialEq,Eq,Hash)]enum GlobalKey{Norm(GlobalPoly),And(GlobalPoly,GlobalPoly)}
struct GlobalAnf{dag:Dag,next:u32,cap:usize,capped:usize,degree:usize,intern:std::collections::HashMap<GlobalKey,(u32,u32)>,intern_bytes:usize,hits:usize,clears:usize}
impl GlobalAnf{
 fn new(cap:usize)->Self{Self{dag:Dag::new(),next:0,cap,capped:0,degree:16,intern:std::collections::HashMap::new(),intern_bytes:0,hits:0,clears:0}}
 fn constant(x:u32)->GlobalPoly{if x==0{GlobalPoly(Vec::new())}else{GlobalPoly(vec![(Vec::new(),x)])}}
 fn fresh(&mut self)->GlobalPoly{let id=self.next;self.next=self.next.checked_add(1).unwrap();GlobalPoly(vec![(vec![id],1)])}
 fn or(&mut self,a:u32,b:u32)->u32{let a=self.dag.find(a);let b=self.dag.find(b);if a==1||b==1{return 1;}if a==0{return b;}if b==0||a==b{return a;}if self.dag.complementary(a,b){return 1;}if self.dag.has_and_factor(b,a){return a;}if self.dag.has_and_factor(a,b){return b;}let xy=self.dag.and(a,b);let sum=self.dag.xor(a,b);self.dag.xor(sum,xy)}
 fn summary(&mut self,p:&GlobalPoly)->(u32,u32){let(mut c,mut d)=(0,0);for(k,v)in&p.0{if k.is_empty(){c=self.dag.xor(c,*v)}else{d=self.or(d,*v)}}(c,d)}
 fn key_bytes(k:&GlobalKey)->usize{let p=|p:&GlobalPoly|64+p.0.iter().map(|(k,_)|40+k.len()*4).sum::<usize>();match k{GlobalKey::Norm(a)=>p(a),GlobalKey::And(a,b)=>p(a)+p(b)}}
 fn opaque(&mut self,c:u32,d:u32,key:GlobalKey)->GlobalPoly{self.capped+=1;if d==0{return Self::constant(c);}let(id,mask)=if let Some(pair)=self.intern.get(&key){self.hits+=1;*pair}else{let id=self.next;self.next=self.next.checked_add(1).unwrap();let bytes=Self::key_bytes(&key);let budget=64*1024*1024;if bytes<=budget{if self.intern_bytes+bytes>budget{self.intern.clear();self.intern_bytes=0;self.clears+=1;}self.intern_bytes+=bytes;self.intern.insert(key,(id,d));}(id,d)};assert_eq!(self.dag.find(mask),self.dag.find(d));let mut p=Self::constant(c);p.0.push((vec![id],d));p}
 fn capped_terms(&mut self,mut terms:std::collections::BTreeMap<Vec<u32>,u32>)->GlobalPoly{let c=terms.remove(&Vec::new()).unwrap_or(0);let mut d=0;for v in terms.values(){d=self.or(d,*v);}self.opaque(c,d,GlobalKey::Norm(GlobalPoly(terms.into_iter().collect())))}
 fn xor(&mut self,a:&GlobalPoly,b:&GlobalPoly)->GlobalPoly{if a==b{return Self::constant(0);}if a.0.is_empty(){return b.clone();}if b.0.is_empty(){return a.clone();}let mut terms=std::collections::BTreeMap::<Vec<u32>,u32>::new();for(k,v)in a.0.iter().chain(&b.0){let new=self.dag.xor(terms.get(k).copied().unwrap_or(0),*v);if new==0{terms.remove(k);}else{terms.insert(k.clone(),new);}}if terms.len()-usize::from(terms.contains_key(&Vec::new()))>self.cap{return self.capped_terms(terms);}GlobalPoly(terms.into_iter().collect())}
 fn and(&mut self,a:&GlobalPoly,b:&GlobalPoly)->GlobalPoly{if a.0.is_empty()||b.0.is_empty(){return Self::constant(0);}if a==b{return a.clone();}let(a,b)=if a<=b{(a,b)}else{(b,a)};let fallback=|alg:&mut Self|{let(ac,ad)=alg.summary(a);let(bc,bd)=alg.summary(b);let bvalue=alg.or(bc,bd);let depa=alg.dag.and(ad,bvalue);let depb=alg.dag.and(bd,ac);let d=alg.or(depa,depb);let c=alg.dag.and(ac,bc);alg.opaque(c,d,GlobalKey::And(a.clone(),b.clone()))};if a.0.len()*b.0.len()>(self.cap+1)*(self.cap+1){return fallback(self);}let mut terms=std::collections::BTreeMap::<Vec<u32>,u32>::new();for(ka,va)in&a.0{for(kb,vb)in&b.0{let coefficient=self.dag.and(*va,*vb);if coefficient==0{continue;}let mut key=ka.clone();key.extend(kb);key.sort_unstable();key.dedup();if key.len()>self.degree{return fallback(self);}let old=terms.get(&key).copied().unwrap_or(0);let new=self.dag.xor(old,coefficient);if new==0{terms.remove(&key);}else{terms.insert(key,new);}}}if terms.len()-usize::from(terms.contains_key(&Vec::new()))>self.cap{return self.capped_terms(terms);}GlobalPoly(terms.into_iter().collect())}
 fn not(&mut self,a:&GlobalPoly)->GlobalPoly{self.xor(a,&Self::constant(1))}
}
#[cfg(test)]mod global_anf_tests{use super::*;
 pub(super) fn eval(d:&Dag,id:u32,assignment:u64)->bool{let n=d.nodes[id as usize];match n.kind{0=>false,1=>true,2=>(assignment>>(n.a-2))&1!=0,3=>eval(d,n.a,assignment)^eval(d,n.b,assignment),4=>eval(d,n.a,assignment)&eval(d,n.b,assignment),7=>d.large_defs[n.a as usize].iter().fold(false,|a,m|a^d.monomials[*m as usize].iter().all(|i|eval(d,*i,assignment))),8=>[n.a,n.b].iter().all(|m|d.monomials[*m as usize].iter().all(|i|eval(d,*i,assignment))),_=>unreachable!()}}
 fn peval(a:&GlobalAnf,p:&GlobalPoly,input:u64,random:u64)->bool{p.0.iter().fold(false,|acc,(key,c)|acc^(eval(&a.dag,*c,input)&&key.iter().all(|x|random>>x&1!=0)))}
 #[test]fn conditional_compute_reset_and_negative_rng_dependency(){let mut a=GlobalAnf::new(32);let i=a.dag.variable(false);let j=a.dag.variable(false);let f=a.dag.and(i,j);let f=GlobalAnf::constant(f);let m=a.fresh();let q=a.and(&f,&m);let nm=a.not(&m);let cleared=a.and(&q,&nm);assert!(cleared.0.is_empty());let negative=a.and(&f,&nm);assert!(negative.0.iter().any(|(k,_)|!k.is_empty()));}
 #[test]fn all_two_input_two_rng_assignments_exact(){let mut a=GlobalAnf::new(32);let i=a.dag.variable(false);let j=a.dag.variable(false);let p=GlobalPoly(vec![(vec![],i),(vec![0],j),(vec![1],1),(vec![0,1],i)]);let q=GlobalPoly(vec![(vec![],j),(vec![1],i)]);a.next=2;let mul=a.and(&p,&q);let xor=a.xor(&p,&q);let not=a.not(&p);for input in 0..4{for random in 0..4{assert_eq!(peval(&a,&mul,input,random),peval(&a,&p,input,random)&peval(&a,&q,input,random));assert_eq!(peval(&a,&xor,input,random),peval(&a,&p,input,random)^peval(&a,&q,input,random));assert_eq!(peval(&a,&not,input,random),!peval(&a,&p,input,random));}}}
 #[test]fn capped_constant_separation_and_nonrecycled_ids(){let mut a=GlobalAnf::new(1);let i=a.dag.variable(false);let m=a.fresh();let n=a.fresh();let p=a.xor(&m,&n);let literal=GlobalPoly(vec![(vec![0],1),(vec![1],1)]);let v=a.xor(&literal,&GlobalAnf::constant(i));let z=a.xor(&p,&v);assert!(z==GlobalAnf::constant(i));assert!(a.hits>0);let old=a.next;a.intern.clear();a.intern_bytes=0;let _=a.xor(&m,&n);assert!(a.next>old);assert!(p.0.iter().any(|(k,_)|!k.is_empty()));}
 #[test]fn capped_dependency_mask_is_sound_for_each_input(){let mut a=GlobalAnf::new(1);let i=a.dag.variable(false);let j=a.dag.variable(false);a.next=2;let x=GlobalPoly(vec![(vec![],i),(vec![0],j),(vec![1],i)]);let y=GlobalPoly(vec![(vec![],j),(vec![1],1)]);let z=a.and(&x,&y);assert!(a.capped>0);let(c,d)=a.summary(&z);for input in 0..4{if !eval(&a.dag,d,input){for random in 0..4{assert_eq!(eval(&a.dag,c,input),peval(&a,&x,input,random)&peval(&a,&y,input,random));}}}}
 #[test]fn input_dag_exact_boolean_rewrites_all_assignments(){let mut d=Dag::new();let v:Vec<_>=(0..6).map(|_|d.variable(false)).collect();let mut expressions=v;let mut seed=413283u64;for i in 0..300{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);let x=expressions[seed as usize%expressions.len()];seed=seed.rotate_left(19);let y=expressions[seed as usize%expressions.len()];let and=i%3==0;let z=if and{d.and(x,y)}else{d.xor(x,y)};for bits in 0..64{assert_eq!(eval(&d,z,bits),if and{eval(&d,x,bits)&eval(&d,y,bits)}else{eval(&d,x,bits)^eval(&d,y,bits)});}expressions.push(z);}}
}

#[cfg(test)]mod or_mask_tests{use super::*;
 #[test]fn saturation_never_expands_a_large_dependency_mask(){let mut a=GlobalAnf::new(32);let mut x=0;for _ in 0..64{let v=a.dag.variable(false);x=a.dag.xor(x,v);}let before=a.dag.nodes.len();assert_eq!(a.or(x,1),1);assert_eq!(a.or(1,x),1);assert_eq!(a.or(x,x),x);assert_eq!(a.dag.nodes.len(),before);let y=a.dag.variable(false);let xy=a.dag.and(x,y);assert_eq!(a.or(x,xy),x);}
}


#[cfg(test)]mod input_anf_tests{use super::*;
 fn values(d:&Dag,seed:u64)->Vec<bool>{let mut v=vec![false;d.nodes.len()];v[1]=true;for(i,n)in d.nodes.iter().enumerate().skip(2){v[i]=match n.kind{2=>{let mut x=(i as u64)^seed.wrapping_mul(0x9e3779b97f4a7c15);x=(x^(x>>30)).wrapping_mul(0xbf58476d1ce4e5b9);x=(x^(x>>27)).wrapping_mul(0x94d049bb133111eb);(x^(x>>31))&1!=0},3=>v[n.a as usize]^v[n.b as usize],4=>v[n.a as usize]&v[n.b as usize],7=>d.large_defs[n.a as usize].iter().fold(false,|a,m|a^d.monomials[*m as usize].iter().all(|i|v[*i as usize])),8=>[n.a,n.b].iter().all(|m|d.monomials[*m as usize].iter().all(|i|v[*i as usize])),_=>panic!()};}for(i,p)in d.polys.iter().enumerate(){let actual=p.atoms.iter().fold(p.constant,|a,m|a^d.monomials[*m as usize].iter().all(|j|v[*j as usize]));assert_eq!(actual,v[i],"input coefficient polynomial semantics at node{i}");}v}
 #[test]fn large_input_only_caps_keep_constants_and_semantics(){let mut d=Dag::new();let mut x=0;let mut operations=Vec::new();for _ in 0..1000{let v=d.variable(false);let old=x;x=d.xor(x,v);operations.push((old,v,x,false));}let nx=d.not(x);let y=d.variable(false);let xy=d.xor(x,y);assert_eq!(d.xor(xy,y),d.find(x));assert_eq!(d.and(x,nx),0);let product=d.and(x,y);let nm=d.not(product);assert_eq!(d.and(product,nm),0);for seed in 0..64{let v=values(&d,seed);for(a,b,c,is_and)in &operations{assert_eq!(v[*c as usize],if *is_and{v[*a as usize]&v[*b as usize]}else{v[*a as usize]^v[*b as usize]});}assert_eq!(v[nx as usize],!v[x as usize]);assert_eq!(v[product as usize],v[x as usize]&v[y as usize]);for i in 0..d.nodes.len(){assert_eq!(v[i],v[d.find(i as u32)as usize]);}}assert!(d.nodes.iter().any(|n|n.kind==7));}
 #[test]fn square_free_distribution_proves_conditional_cancellation(){let mut d=Dag::new();let a=d.variable(false);let b=d.variable(false);let c=d.variable(false);let ab=d.and(a,b);let cab=d.and(c,ab);let nc=d.not(c);let z=d.and(cab,nc);assert_eq!(z,0);let nab=d.not(ab);let k=d.and(cab,nab);assert_eq!(k,0);}
 #[test]fn monomial_overflow_atoms_keep_exact_semantics(){let mut d=Dag::new();let mut x=1;let mut ops=Vec::new();for _ in 0..300{let v=d.variable(false);let old=x;x=d.and(x,v);ops.push((old,v,x));}assert!(d.nodes.iter().any(|n|n.kind==8));for seed in 0..64{let v=values(&d,seed);for(a,b,c)in &ops{assert_eq!(v[*c as usize],v[*a as usize]&v[*b as usize]);}}}
}

#[cfg(test)]mod input_product_cap_tests{use super::*;
 #[test]fn retained_input_product_constants_cancel_exactly(){let mut d=Dag::new();let(mut x,mut y)=(0,0);for _ in 0..20{let v=d.variable(false);x=d.xor(x,v);let v=d.variable(false);y=d.xor(y,v);}let xy=d.and(x,y);let nx=d.not(x);let ny=d.not(y);let nn=d.and(nx,ny);let mut expected=d.xor(xy,x);expected=d.xor(expected,y);expected=d.not(expected);let z=d.xor(nn,expected);assert_eq!(z,0);assert!(!d.nodes[xy as usize].random);}
}

#[cfg(test)]mod hybrid_bdd_tests{use super::*;
 #[test]fn exact_classical_masks_cancel_through_opaque_quantum_data(){let mut d=Dag::new();let mut data=0;for _ in 0..1000{let v=d.variable(false);data=d.xor(data,v);}let a=d.variable(false);d.mark_classical(a);let b=d.variable(false);d.mark_classical(b);let ab=d.and(a,b);let nab=d.not(ab);let x=d.and(data,ab);let z=d.and(x,nab);assert_eq!(z,0);let y=d.and(data,nab);let joined=d.xor(x,y);assert_eq!(d.xor(joined,data),0);}
 #[test]fn classical_bdd_nodes_preserve_exact_semantic_trace(){let mut d=Dag::new();let v:Vec<_>=(0..6).map(|_|{let x=d.variable(false);d.mark_classical(x);x}).collect();let mut expressions=v;let mut seed=7213u64;for i in 0..300{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);let x=expressions[seed as usize%expressions.len()];seed=seed.rotate_left(17);let y=expressions[seed as usize%expressions.len()];let and=i%3==0;let z=if and{d.and(x,y)}else{d.xor(x,y)};for bits in 0..64{let eval=|id|global_anf_tests::eval(&d,id,bits);assert_eq!(eval(z),if and{eval(x)&eval(y)}else{eval(x)^eval(y)});assert_eq!(d.bdd.eval(d.node_bdd[z as usize].unwrap(),bits),eval(z));}expressions.push(z);}}
}

#[cfg(test)]mod mixed_hybrid_tests{use super::*;
 fn check(cap:usize){let mut d=Dag::new();d.bdd.cap=cap;let v:Vec<_>=(0..6).map(|i|{let x=d.variable(false);if i>=3{d.mark_classical(x);}x}).collect();let mut expressions=v;let mut seed=517497u64;for i in 0..500{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);let x=expressions[seed as usize%expressions.len()];seed=seed.rotate_left(23);let y=expressions[seed as usize%expressions.len()];let and=i%3==0;let z=if and{d.and(x,y)}else{d.xor(x,y)};for bits in 0..64{let eval=|id|global_anf_tests::eval(&d,id,bits);assert_eq!(eval(z),if and{eval(x)&eval(y)}else{eval(x)^eval(y)});}expressions.push(z);}}
 #[test]fn mixed_quantum_and_classical_functions_exact_all_assignments(){check(100000);}
 #[test]fn mixed_budget_failures_preserve_exact_semantics(){check(8);}
}
